-- Source: schemas/functions/duty_private/assert_admin_remains.sql
CREATE FUNCTION duty_private.assert_admin_remains() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if not exists(select 1 from public.duty_members m join public.duty_roles r on r.code=m.role where m.active and m.status='approved' and r.can_manage) then raise exception 'Keep at least one active admin'; end if;
end $$;

-- Source: schemas/functions/duty_private/check_revision.sql
CREATE FUNCTION duty_private.check_revision(p_revision bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare current_revision bigint;
begin
 if not duty_private.is_member() then raise exception 'Your membership is not approved' using errcode='42501'; end if;
 select revision into current_revision from public.duty_workspace where id for update;
 if current_revision is distinct from p_revision then raise exception 'The team data changed. Refresh and try again.' using errcode='40001'; end if;
end $$;


