CREATE FUNCTION duty_private.duty_owner(p_day date) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select to_char(case when extract(dow from p_day)=6 then p_day-1 else p_day end,'YYYY-MM')
$$;

-- Source: schemas/functions/duty_private/is_manager.sql
CREATE FUNCTION duty_private.is_manager() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and exists(select 1 from public.duty_members m join public.duty_roles r on r.code=m.role where m.id=auth.uid() and r.can_manage and m.status='approved' and m.active)
$$;

